var i=`0657-pounded-yam`;var n=`world-0657`;var a=`NG`;var s=`western-africa`;var r=4;var o=56;var d={en:`Pounded Yam`,ua:`Товчений ямс`};var u={en:`Pounded Yam is a Nigeria classic prepared with yam. A measured home-style version, with ingredients assigned to the cooking steps where they are used. Use true yam tubers; plantain, sweet potato and ordinary potatoes are not equivalent substitutes.`,ua:`Товчений ямс, страва кухні країни Нігерія зі складниками: ямс. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування. Потрібен справжній ямс: плантан, батат та звичайна картопля не є рівнозначною заміною.`};var l=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`yam`,1050,`g`]]},{en:`Cook the listed ingredients in simmering water for about 28 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 28 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:28,i:[[`water`,1300,`ml`],[`table-salt`,4,`g`]]},{en:`Pound hot, drained yam repeatedly until the pieces disappear and the mixture becomes stretchy and glossy; do not add flour or oil.`,ua:`Інтенсивно товчіть гарячий обсушений ямс до зникнення грудочок і гладкої тягучої текстури; не додавайте борошно чи олію.`,t:[`mashing`,`pounding`],m:15,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`water`,40,`ml`]]}];var m={slug:i,id:n,country:`NG`,region:s,servings:4,minutes:56,title:d,text:u,steps:l};export{a as country,m as default,n as id,o as minutes,s as region,r as servings,i as slug,l as steps,u as text,d as title};